  '[{"id":"tc1","validation_type":"matching","expected_value":"Total revenue","description_en":"SUM","description_id":"SUM","points":25},{"id":"tc2","validation_type":"matching","expected_value":"Number of distinct orders","description_en":"DISTINCTCOUNT","description_id":"DISTINCTCOUNT","points":25},{"id":"tc3","validation_type":"matching","expected_value":"Average order value","description_en":"DIVIDE","description_id":"DIVIDE","points":25},{"id":"tc4","validation_type":"matching","expected_value":"Mean order amount","description_en":"AVERAGE","description_id":"AVERAGE","points":25}]',
